import Fulfillment from './Fulfillment'
import AppSession from './AppSession'
import LoginMaintenance from './LoginMaintenance'
import { WorkspaceContext,useWorkspace } from './context'
import { PanelsPage,ProxiesPage } from './ManagementPages'
import TaskCoverage from './TaskCoverage'
import { MenuOutlined } from '@ant-design/icons'
import { createContext, useCallback, useContext, useEffect, useRef, useState } from 'react'
import { Alert, App as AntApp, Avatar, Badge, Button, Checkbox, Descriptions, Drawer, Empty, Form, Input, InputNumber, Modal, Pagination, Popconfirm, Progress, Radio, Select, Segmented, Skeleton, Space, Spin, Table, Tabs, Tag, Tooltip, Upload } from 'antd'
import { ArrowDownOutlined, ArrowRightOutlined, ArrowUpOutlined, BellOutlined, CheckCircleOutlined, CheckOutlined, ClockCircleOutlined, CloudDownloadOutlined, DashboardOutlined, DatabaseOutlined, DownloadOutlined, ExclamationCircleOutlined, FileTextOutlined, GiftOutlined, InfoCircleOutlined, LeftOutlined, LogoutOutlined, MoreOutlined, PauseCircleOutlined, PlayCircleOutlined, PlusOutlined, QuestionCircleOutlined, ReloadOutlined, RightOutlined, SearchOutlined, SettingOutlined, ShopOutlined, StopOutlined, SyncOutlined, TeamOutlined, TrophyOutlined, UploadOutlined, WalletOutlined } from '@ant-design/icons'
import { Area, AreaChart, CartesianGrid, ResponsiveContainer, Tooltip as ChartTooltip, XAxis, YAxis } from 'recharts'
import dayjs from 'dayjs'
import { api, download, type Mode, type Row } from './api'
import TaskStepDetails,{taskStepMessage} from './TaskStepDetails'
import SettingsPage from './SettingsPage'
import { CatalogJob,LiveCatalogButton } from './LiveCatalog'
import RedemptionDialog from './RedemptionDialog'

type ContextValue = { mode: Mode; refresh: number; reload: () => void; navigate: (route:string) => void }
const Context = WorkspaceContext
const useApp = useWorkspace
const number = (value:unknown) => Number(value || 0).toLocaleString('zh-CN')
const time = (value:unknown, format='MM-DD HH:mm:ss') => value ? dayjs(String(value)).format(format) : '—'
const statusMap:Record<string,[string,string]> = {active:['正常','success'],healthy:['可用','success'],unverified:['待检测','default'],connected:['已连接','success'],unreachable:['不可达','error'],pending_login:['待登录','processing'],expired:['登录过期','warning'],disabled:['已停用','default'],completed:['已完成','success'],running:['执行中','processing'],pending:['待执行','default'],paused:['已暂停','warning'],stopping:['停止中','warning'],stopped:['已停止','default'],failed:['失败','error'],partial:['部分完成','warning'],skipped:['已跳过','default'],cancelled:['已取消','default'],success:['兑换成功','success'],unknown:['待核实','warning'],captcha_required:['需安全验证','warning'],sms_required:['需短信验证','warning']}
function Status({value}:{value:string}) { const entry=statusMap[value]||[value,'default'];return <Tag bordered={false} className="status-tag" color={entry[1]}><span className={`status-dot ${entry[1]}`}/>{entry[0]}</Tag> }
function useLoad<T = Row>(path:string,interval=0) {
  const {mode,refresh}=useApp(); const [data,setData]=useState<T|null>(null);const [error,setError]=useState('');const [loading,setLoading]=useState(true)
  useEffect(()=>{let alive=true;setLoading(true);setData(null);const load=()=>api<T>(path,mode).then(d=>{if(alive){setData(d);setError('');setLoading(false)}}).catch(e=>{if(alive){setError(e.message);setLoading(false)}});load();const timer=interval?setInterval(load,interval):undefined;return()=>{alive=false;clearInterval(timer)}},[path,mode,refresh,interval])
  return {data,error,loading}
}
function LoadError({error}:{error:string}) {return error?<Alert type="error" showIcon message={error} style={{marginBottom:18}}/>:null}
function WorkflowBanner({onSelect}:{onSelect?:(id:string)=>void}={}){const {mode}=useApp();const {data}=useLoad('/workflows',5000);const items=data?.items||[];const row=items.find((r:Row)=>r.status==='active'&&r.stage==='running')||items.find((r:Row)=>r.status==='active')||items[0];return mode==='live'&&row?<Alert className="import-status" showIcon type={row.status==='completed'?'success':'info'} message={`全量执行流程 · ${row.stage==='awaiting_authorization'?'等待公开代理用途授权':row.stage==='waiting_proxy'?'等待可用代理':row.stage==='discovering'?'同步应用宝账号':row.stage==='running'?'正在执行':row.stage?.startsWith('waiting_batch:')?'等待前序任务':row.stage==='completed'?'已处理完毕':'已暂停'}`} description={row.message} action={onSelect?<Button size="small" onClick={()=>onSelect(row.batch_id)}>查看全量批次</Button>:undefined}/>:null}
const balance=(v:unknown)=>v===null?'未同步':number(v)
function AccountName({row,rank}:{row:Row;rank?:number}) {return <div className="account-name">{rank!==undefined&&<span className={`rank-number rank-${rank}`}>{rank<4?<TrophyOutlined/>:rank}</span>}<Avatar shape="square" size={34} style={{background:['#eaf0fd','#e9f4f0','#f5ede6','#eeebf6'][Number(row.id||row.account_id)%4],color:['#5677bd','#4b8e79','#ac815c','#8a70ab'][Number(row.id||row.account_id)%4]}}>{String(row.nickname||'V').slice(0,1)}</Avatar><span><strong>{row.nickname}</strong><small>{row.phone || `ID ${String(row.id||row.account_id).padStart(6,'0')}`}</small></span></div>}
function PageHead({title,description,children}:{title:string;description:string;children?:React.ReactNode}) {return <div className="page-head"><div><h1>{title}</h1><p>{description}</p></div><div className="page-actions">{children}</div></div>}
function Panel({title,extra,children,className=''}:{title:React.ReactNode;extra?:React.ReactNode;children:React.ReactNode;className?:string}) {return <section className={`panel ${className}`}><div className="panel-head"><h2>{title}</h2>{extra}</div>{children}</section>}
function Metric({label,value,icon,sub,color='blue'}:{label:string;value:React.ReactNode;icon:React.ReactNode;sub:React.ReactNode;color?:string}) {return <div className="metric"><div className="metric-label">{label}<span className={`metric-icon ${color}`}>{icon}</span></div><div className="metric-value">{value}</div><div className="metric-sub">{sub}</div></div>}

function StartBatch({ids,children,type='primary',retry}:{ids?:number[];children?:React.ReactNode;type?:'primary'|'default'|'text';retry?:string}) {
  const {mode,reload,navigate}=useApp();const {message}=AntApp.useApp();const [open,setOpen]=useState(false);const [busy,setBusy]=useState(false);const [profile,setProfile]=useState('full');const [concurrency,setConcurrency]=useState(20)
  useEffect(()=>{if(open)api('/settings',mode).then(d=>setConcurrency(d.concurrency)).catch(()=>{})},[open,mode])
  async function start(){setBusy(true);try{await api('/batches',mode,{method:'POST',body:JSON.stringify({profile,concurrency,account_ids:ids,retry_batch:retry})});setOpen(false);message.success('任务批次已创建，正在执行');reload();navigate('tasks')}catch(e){message.error((e as Error).message)}finally{setBusy(false)}}
  return <><Button type={type} icon={<PlayCircleOutlined/>} onClick={()=>setOpen(true)} disabled={ids!==undefined&&!ids.length}>{children||'执行全部任务'}</Button><Modal title={retry?'重试未完成账号':'创建任务批次'} open={open} onCancel={()=>setOpen(false)} onOk={start} confirmLoading={busy} okText="开始执行" cancelText="取消"><div className="modal-intro">{retry?'只重新执行该批次中失败或部分完成的账号。':ids?`将执行已选择的 ${ids.length} 个账号。`:'将覆盖当前库内全部账号，不受列表分页和筛选影响。停用与登录过期账号也会纳入结果。'}</div>{mode==='demo'&&<Alert showIcon type="info" message="当前为演示模式，任务不会访问 vivo 平台"/>}<Form layout="vertical" style={{marginTop:20}}><Form.Item label="执行方案"><Radio.Group value={profile} onChange={e=>setProfile(e.target.value)}><Space direction="vertical"><Radio value="full">全量任务 <span className="muted">签到、任务中心、活动与会员权益</span></Radio><Radio value="daily">每日签到 <span className="muted">签到、连签与日常权益</span></Radio><Radio value="sync">仅同步积分 <span className="muted">刷新真实积分余额</span></Radio></Space></Radio.Group></Form.Item><Form.Item label="同时执行的账号数"><InputNumber min={1} max={256} value={concurrency} onChange={v=>setConcurrency(v||1)}/><span className="field-help">单账号内按顺序执行，失败步骤单独记录</span></Form.Item></Form><p className="form-note">真实任务沿用参考项目的积分获取模式。需要身份验证、设备交互或平台不支持的任务会保留实际结果。</p></Modal></>
}

function Dashboard(){
  const {mode,navigate,reload}=useApp();const {data,error,loading}=useLoad('/overview',8000)
  if(!data)return <><PageHead title="运营总览" description="所有账号、任务与积分动态，尽在掌握。"/><LoadError error={error}/>{loading&&<Skeleton active paragraph={{rows:12}}/>}</>
  const b=data.latest_batch;const done=b?b.completed+b.failed+b.skipped+b.cancelled:0;const percent=b?Math.round(done/b.total*100):0
  const earned=data.trend.reduce((sum:number,r:Row)=>sum+r.earned,0)
  return <><PageHead title="运营总览" description={`欢迎回来，今天是 ${dayjs().format('YYYY年M月D日')}，一起看看账号的运营情况。`}><Button icon={<ReloadOutlined/>} onClick={reload}>刷新数据</Button><StartBatch/></PageHead><LoadError error={error}/>
    <div className="context-strip"><div><span className="live-dot"/>系统运行正常<span className="strip-separator"/>当前管理 <b>{number(data.counts.total)}</b> 个账号<span className="strip-separator"/><span className="muted">{mode==='demo'?'演示工作区 · 数据与真实账号隔离':'真实工作区 · 账号数据'}</span></div><span className="muted">更新于 {time(data.time,'HH:mm:ss')}</span></div>
    <div className="metric-grid"><Metric label="账号总数" value={number(data.counts.total)} icon={<TeamOutlined/>} sub={<><span className="green">{number(data.counts.active)} 个正常</span><span className="metric-divider"/> {number(Number(data.counts.expired)+Number(data.counts.disabled)+Number(data.counts.pending_login))} 个待关注</>}/><Metric label="可用积分总额" value={<>{number(data.counts.points)}<em>积分</em></>} icon={<WalletOutlined/>} color="purple" sub={<>{data.counts.unsynced?`${number(data.counts.unsynced)} 个余额待同步`:'全部账号积分汇总'} <Tooltip title="按本地最近同步的账号积分汇总，兑换前请确认余额"><InfoCircleOutlined/></Tooltip></>}/><Metric label="今日获得积分" value={<>{number(data.today_earned)}<em>积分</em></>} icon={<ArrowUpOutlined/>} color="green" sub={<><span className="green"><ArrowUpOutlined/> 收益持续汇总</span><span className="metric-divider"/>7 日 {number(earned)}</>}/><Metric label="累计兑换成功" value={<>{number(data.redemptions)}<em>笔</em></>} icon={<GiftOutlined/>} color="orange" sub={<a onClick={()=>navigate('redemptions')}>查看已兑换商品 <ArrowRightOutlined/></a>}/></div>
    <div className="dashboard-charts"><Panel title="积分收支趋势" extra={<Space size={20}><span className="chart-key"><i/>获得积分</span><span className="chart-key spent"><i/>兑换消耗</span><Tag className="subtle-tag">近 7 天</Tag></Space>}><div className="chart-summary"><strong>{number(earned)}</strong><span>近 7 天累计获得积分</span></div><div className="trend-chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={data.trend} margin={{top:10,right:20,left:0,bottom:0}}><defs><linearGradient id="earnedFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#3869ed" stopOpacity={.13}/><stop offset="100%" stopColor="#3869ed" stopOpacity={.005}/></linearGradient></defs><CartesianGrid strokeDasharray="3 5" vertical={false} stroke="#edf0f5"/><XAxis dataKey="date" axisLine={false} tickLine={false} tick={{fill:'#929baa',fontSize:11}} dy={10}/><YAxis axisLine={false} tickLine={false} tick={{fill:'#929baa',fontSize:11}} width={52} tickFormatter={v=>v>=10000?`${v/10000}万`:String(v)}/><ChartTooltip contentStyle={{border:'1px solid #e8ecf2',borderRadius:6,fontSize:12}} formatter={(value,name)=>[number(value),name==='earned'?'获得积分':'兑换消耗']}/><Area type="monotone" dataKey="earned" stroke="#3669e9" strokeWidth={2.5} fill="url(#earnedFill)" dot={{r:3,fill:'#fff',strokeWidth:2}} activeDot={{r:5}}/><Area type="monotone" dataKey="spent" stroke="#70b8a3" strokeWidth={2} strokeDasharray="4 4" fill="transparent"/></AreaChart></ResponsiveContainer></div></Panel>
    <Panel title="最近任务执行" extra={<a onClick={()=>navigate('tasks')}>任务中心 <RightOutlined/></a>}>{b?<><div className="task-ring"><Progress type="circle" percent={percent} size={142} strokeWidth={9} strokeColor="#315fdf" trailColor="#eef2f8" format={v=><div className="ring-label"><strong>{v}<em>%</em></strong><span>批次处理进度</span></div>}/></div><div className="task-legend"><div><span><i className="dot blue"/>成功完成</span><b>{number(b.completed)}</b></div><div><span><i className="dot orange"/>失败 / 部分完成</span><b>{number(b.failed)}</b></div><div><span><i className="dot gray"/>已跳过 / 已取消</span><b>{number(b.skipped+b.cancelled)}</b></div><div><span><i className="dot pale"/>等待 / 正在执行</span><b>{number(b.pending+b.running)}</b></div></div><div className="task-foot"><ClockCircleOutlined/> {time(b.created_at,'HH:mm')} 创建 · {number(b.total)} 个账号 <Status value={b.status}/></div></>:<Empty description="尚未创建任务批次"/>}</Panel></div>
    <div className="dashboard-bottom"><Panel title="积分排行榜" extra={<a onClick={()=>navigate('ranking')}>完整排行 <RightOutlined/></a>}><Table<Row> size="small" rowKey="id" dataSource={data.top_accounts} pagination={false} columns={[{title:'排名 / 账号',key:'name',render:(_,r,i)=><AccountName row={r} rank={i+1}/>},{title:'可用积分',dataIndex:'points',align:'right',render:v=><b className="numeric">{balance(v)}</b>},{title:'最近收益',dataIndex:'gained',align:'right',render:v=><span className="green">+{number(v)}</span>}]} locale={{emptyText:<Empty description="导入账号后查看排行"/>}}/></Panel><Panel title="最近兑换" extra={<a onClick={()=>navigate('redemptions')}>全部记录 <RightOutlined/></a>}><div className="recent-orders">{data.recent_orders.length?data.recent_orders.map((r:Row)=><div className="recent-order" key={r.id}><ProductArt art={r.art} compact/><div className="recent-order-copy"><strong>{r.product_name}</strong><span>{r.nickname} · {time(r.created_at,'MM-DD HH:mm')}</span></div><div className="recent-order-result"><b>{number(r.price)} <small>积分</small></b><Status value={r.status}/></div></div>):<Empty description="暂无兑换记录"/>}</div></Panel></div>
  </>
}

function EngineSummary(){const {mode}=useApp();const {data}=useLoad('/engine',5000);return mode==='live'?<div className="management-summary"><div><span>已启动 / 配置进程</span><strong>{number(data?.worker_processes)}<small style={{fontSize:13,color:'#99a5b5'}}> / {number(data?.configured_processes)}</small></strong></div><div><span>正在处理的账号</span><strong>{number(data?.busy_accounts??data?.busy_processes)}</strong></div><div><span>已保存步骤断点</span><strong>{number(data?.checkpoint_count)}</strong></div><div><span>已记录任务请求</span><strong>{number(data?.request_count)}</strong></div></div>:null}

function ImportAccounts({open,onClose}:{open:boolean;onClose:()=>void}) {
  const {mode,reload}=useApp();const {message}=AntApp.useApp();const [text,setText]=useState('');const [busy,setBusy]=useState(false)
  async function importIt(discover=false){setBusy(true);try{const result=await api(discover?'/accounts/discover':'/accounts/import',mode,{method:'POST',body:discover?'{}':text});message.success(`处理 ${result.processed} 条，新增 ${result.added} 个，更新 ${result.updated} 个账号`);reload();onClose();setText('')}catch(e){message.error((e as Error).message)}finally{setBusy(false)}}
  return <Modal title="导入账号" destroyOnHidden open={open} onCancel={onClose} onOk={()=>importIt()} okText="确认导入" cancelText="取消" confirmLoading={busy} width={640}><p className="modal-intro">支持参考项目的 accounts.json 缓存或标准 JSON 数组。按 openid 去重，已有账号更新凭证，所有账号全量保存。</p><Upload accept=".json" showUploadList={false} beforeUpload={async file=>{setText(await file.text());return false}}><Button icon={<UploadOutlined/>}>选择 JSON 文件</Button></Upload><Input.TextArea style={{marginTop:14,fontFamily:'monospace'}} rows={8} value={text} onChange={e=>setText(e.target.value)} placeholder={'[\n  {"openid":"账号标识", "vivotoken":"登录凭证",\n   "nickname":"账号昵称", "phone":"手机号"}\n]'}/><div className="import-footer"><span><CheckCircleOutlined/> 凭证加密保存在本地，不在列表或导出中展示</span>{mode==='live'&&<Button type="link" onClick={()=>importIt(true)} loading={busy}>从参考项目缓存导入</Button>}</div></Modal>
}

function AccountDrawer({id,onClose}:{id:number|null;onClose:()=>void}) {const {data,error}=useLoad(`/accounts/${id||0}`);return <Drawer width={560} title="账号详情" open={id!==null} onClose={onClose}><LoadError error={id?error:''}/>{data&&id&&<><div className="detail-account"><AccountName row={data.account}/><Status value={data.account.status}/></div><Descriptions bordered column={1} size="small" items={[{key:'id',label:'账号 ID',children:data.account.id},{key:'source',label:'来源',children:data.account.source},{key:'city',label:'城市',children:data.account.city},{key:'device',label:'设备配置',children:data.account.device?`${data.account.device.market_name||data.account.device.brand} ${data.account.device.model} · Android ${data.account.device.android_ver} · ${data.account.device.screensize?.replace('_',' × ')||'—'}（${data.account.device.native_verified?'原设备资料':data.account.device.profile_source==='assigned-vivo'?'随机分配，已保存':'协议配置'}）`:'待核对'},{key:'point',label:'可用积分',children:balance(data.account.points)},{key:'gained',label:'最近收益',children:`${data.account.gained>0?'+':''}${number(data.account.gained)}`},{key:'time',label:'最后执行',children:time(data.account.last_run,'YYYY-MM-DD HH:mm:ss')}]}/><div style={{marginTop:16}}><AppSession accountId={id}/></div><h3 className="drawer-subtitle">最近执行记录</h3>{data.runs.length?data.runs.map((r:Row)=><div className="detail-run" key={r.id}><div><Status value={r.status}/><span>{time(r.finished_at)}</span></div><p>{r.error||`获得 ${number(r.gained)} 积分`}</p></div>):<Empty description="暂无执行记录"/>}<h3 className="drawer-subtitle">积分变动</h3>{data.history.map((r:Row)=><div className="point-row" key={r.id}><div>{r.reason}<small>{time(r.created_at)}</small></div><b className={r.delta>0?'green':''}>{r.delta>0?'+':''}{number(r.delta)}</b></div>)}</>}</Drawer>}

function Accounts(){
  const {mode,reload}=useApp();const {message}=AntApp.useApp();const [q,setQ]=useState('');const [status,setStatus]=useState('all');const [source,setSource]=useState('all');const [page,setPage]=useState(1);const [size,setSize]=useState(15);const [selected,setSelected]=useState<React.Key[]>([]);const [open,setOpen]=useState(false);const [detail,setDetail]=useState<number|null>(null)
  const query=`?page=${page}&page_size=${size}&q=${encodeURIComponent(q)}&status=${status}&source=${encodeURIComponent(source)}`
  const {data,error,loading}=useLoad('/accounts'+query)
  const imports=useLoad('/imports',3000);const job=imports.data?.items?.[0]
  async function syncPools(){try{await api('/accounts/sync-pools',mode,{method:'POST',body:'{}'});message.success('已开始扫描参考项目中的全部面板，账号将逐池入库');reload()}catch(e){message.error((e as Error).message)}}
  const changeStatus=async(r:Row)=>{try{await api(`/accounts/${r.id}`,mode,{method:'PATCH',body:JSON.stringify({status:r.status==='disabled'?'active':'disabled'})});reload();message.success('账号状态已更新')}catch(e){message.error((e as Error).message)}}
  return <><PageHead title="账号管理" description="统一管理所有账号，查看登录状态、积分余额与任务执行情况。"><AppSession/><Button icon={<DownloadOutlined/>} onClick={()=>download('/accounts/export'+query,mode)}>导出账号</Button><Button type="primary" icon={<PlusOutlined/>} onClick={()=>setOpen(true)}>导入账号</Button>{mode==='live'&&<Button icon={<SyncOutlined spin={job?.status==='running'}/>} disabled={job?.status==='running'} onClick={syncPools}>同步全部面板</Button>}</PageHead><LoadError error={error}/>{job&&<Alert className="import-status" showIcon type={job.status==='running'?'info':job.failed?'warning':'success'} message={`面板同步：${job.processed} / ${job.total} 个面板，新增 ${number(job.accounts)} 个账号，失败 ${job.failed} 个面板`} description={job.status==='running'?'正在逐池全量读取，离线账号也会保留。完成后刷新账号列表查看。':job.message} action={<Button size="small" onClick={reload}>刷新列表</Button>}/>}<div className="account-summary"><span>账号总数 <b>{number(Object.values(data?.counts||{}).reduce((a:any,b:any)=>a+b,0))}</b></span><span><i className="dot green"/>正常 <b>{number(data?.counts.active)}</b></span><span><i className="dot orange"/>登录过期 <b>{number(data?.counts.expired)}</b></span><span><i className="dot gray"/>已停用 <b>{number(data?.counts.disabled)}</b></span><div className="grow"/><span className="muted"><DatabaseOutlined/> 全量入库 · 服务端分页</span></div><section className="panel table-panel"><Tabs activeKey={status} onChange={v=>{setStatus(v);setPage(1)}} items={[{key:'all',label:'全部账号'},{key:'active',label:'正常'},{key:'pending_login',label:'待登录'},{key:'expired',label:'登录过期'},{key:'disabled',label:'已停用'}]}/><div className="table-toolbar"><Input.Search placeholder="搜索昵称、手机号或账号 ID" allowClear style={{width:300}} onSearch={v=>{setQ(v);setPage(1)}}/><Select value={source} style={{width:170}} onChange={v=>{setSource(v);setPage(1)}} options={[{value:'all',label:'全部账号来源'},...(data?.sources||[]).map((s:string)=>({value:s,label:s}))]}/><div className="grow"/>{selected.length>0&&<span className="muted">已选择 {selected.length} 个</span>}<LoginMaintenance ids={selected.map(Number)}/><StartBatch ids={selected.map(Number)} type="default">执行所选账号</StartBatch></div><Table<Row> rowKey="id" loading={loading} dataSource={data?.items||[]} pagination={false} scroll={{x:960}} rowSelection={{selectedRowKeys:selected,onChange:setSelected,preserveSelectedRowKeys:true}} columns={[{title:'账号',key:'account',width:230,render:(_,r)=><AccountName row={r}/>},{title:'账号来源',dataIndex:'source',width:135,render:v=><span className="secondary">{v}</span>},{title:'状态',dataIndex:'status',width:110,render:v=><Status value={v}/>},{title:'可用积分',dataIndex:'points',width:120,align:'right',render:v=><b className="numeric">{balance(v)}</b>},{title:'最近收益',dataIndex:'gained',width:100,align:'right',render:v=><span className={v>0?'green':'muted'}>{v>0?'+':''}{number(v)}</span>},{title:'任务状态',dataIndex:'task_status',width:112,render:v=><Status value={v}/>},{title:'最后执行',dataIndex:'last_run',width:145,render:v=><span className="secondary small">{time(v)}</span>},{title:'操作',key:'action',width:125,render:(_,r)=><Space size={12}><a onClick={()=>setDetail(r.id)}>详情</a><Popconfirm title={r.status==='disabled'?'启用此账号？':'停用此账号？'} onConfirm={()=>changeStatus(r)}><a className="secondary">{r.status==='disabled'?'启用':'停用'}</a></Popconfirm></Space>}]} locale={{emptyText:<Empty description="还没有账号，点击上方导入"/>}}/><div className="table-pagination"><span>共 {number(data?.total)} 个账号</span><Pagination current={page} pageSize={size} total={data?.total||0} showSizeChanger pageSizeOptions={[15,30,50,100]} onChange={(p,s)=>{setPage(p);setSize(s)}}/></div></section><ImportAccounts open={open} onClose={()=>setOpen(false)}/>{detail!==null&&<AccountDrawer id={detail} onClose={()=>setDetail(null)}/>}</>
}

function TaskRuns({bid}:{bid:string}) {
  const [page,setPage]=useState(1);const [status,setStatus]=useState('all');const [run,setRun]=useState<Row|null>(null)
  const {data,error,loading}=useLoad(`/batches/${bid}/runs?page=${page}&page_size=10&status=${status}`,2500)
  const stepData=useLoad(`/runs/${run?.id||0}/steps`,run?2000:0)
  return <><div className="table-toolbar"><span className="secondary">逐账号执行结果</span><div className="grow"/><Select value={status} style={{width:140}} onChange={v=>{setStatus(v);setPage(1)}} options={['all','completed','failed','partial','running','pending','skipped','cancelled'].map(v=>({value:v,label:v==='all'?'全部结果':statusMap[v][0]}))}/></div><LoadError error={error}/><Table<Row> rowKey="id" dataSource={data?.items||[]} loading={loading} pagination={false} columns={[{title:'账号',render:(_,r)=><AccountName row={r}/>},{title:'状态',dataIndex:'status',render:v=><Status value={v}/>},{title:'执行结果',dataIndex:'error',render:(v,r)=><span className={v?'muted':''}>{v||(r.status==='completed'?'任务执行完成':'等待处理')}</span>},{title:'积分增量',dataIndex:'gained',align:'right',render:v=><span className="green">{v>0?'+':''}{number(v)}</span>},{title:'操作',render:(_,r)=><a onClick={()=>setRun(r)}>执行明细</a>}]} scroll={{x:720}}/><div className="table-pagination"><span>覆盖 {number(data?.total)} 个账号</span><Pagination current={page} total={data?.total||0} pageSize={10} onChange={setPage} showSizeChanger={false}/></div><Drawer title={`${run?.nickname||''} · 执行明细`} width={960} open={!!run} onClose={()=>setRun(null)}><Alert type="info" message="每个步骤独立记录，单项失败后继续执行剩余任务。" showIcon style={{marginBottom:20}}/>{stepData.data?.items.length?stepData.data.items.map((s:Row)=><div className="step-item" key={s.id}><div className={`step-icon ${s.status==='completed'?'green':'muted'}`}>{s.status==='completed'?<CheckCircleOutlined/>:<ExclamationCircleOutlined/>}</div><div><div className="step-title"><strong>{s.label}</strong><Status value={s.status}/><small>{time(s.created_at,'HH:mm:ss')}</small></div><p>{taskStepMessage(s)}</p><TaskStepDetails details={s.details}/>{s.elapsed_ms>0&&<small className="muted">{number(s.request_count)} 个请求 · {(s.elapsed_ms/1000).toFixed(1)} 秒</small>}</div></div>):<Empty description={run?.error||'尚无步骤明细；历史演示批次仅保留账号汇总'}/>}</Drawer></>
}

function Tasks(){
  const {mode,reload}=useApp();const {message}=AntApp.useApp();const {data,error,loading}=useLoad('/batches',2000);const [selected,setSelected]=useState<string|null>(null)
  const rows:Row[]=data?.items||[];const batch=rows.find(r=>r.id===selected)||rows[0]
  async function act(action:string){try{await api(`/batches/${batch.id}/${action}`,mode,{method:'POST',body:'{}'});message.success({pause:'已暂停派发，当前账号执行后暂停',resume:'继续执行剩余账号',stop:'停止派发，当前账号执行后结束'}[action]);reload()}catch(e){message.error((e as Error).message)}}
  return <><PageHead title="任务中心" description="多进程并行处理账号，账号内顺序执行，逐步骤保存进度与实际结果。"><TaskCoverage/><StartBatch/></PageHead><LoadError error={error}/><WorkflowBanner onSelect={setSelected}/><EngineSummary/><div className="task-policy"><InfoCircleOutlined/><span>全量覆盖所有账号 · 账号间并发，账号内串行 · 每日已完成任务自动跳过 · 重启后可恢复</span></div><section className="panel task-workspace"><div className="panel-head"><h2>执行批次</h2><Select value={batch?.id} style={{width:260}} placeholder="选择批次" onChange={setSelected} options={rows.map(r=>({value:r.id,label:`${r.name} · ${time(r.created_at)}`}))}/></div>{batch?<><div className="batch-heading"><div><span className="batch-icon"><PlayCircleOutlined/></span><div><h3>{batch.name} <Status value={batch.status}/></h3><p>{batch.id} <span>·</span> {time(batch.created_at,'YYYY-MM-DD HH:mm')} 创建 <span>·</span> {batch.concurrency} 个账号并发</p></div></div><Space>{batch.status==='running'&&<Button icon={<PauseCircleOutlined/>} onClick={()=>act('pause')}>暂停任务</Button>}{batch.status==='paused'&&<Button type="primary" icon={<PlayCircleOutlined/>} onClick={()=>act('resume')}>继续执行</Button>}{['running','paused'].includes(batch.status)&&<Popconfirm title="停止派发剩余任务？正在执行的账号会先完成。" onConfirm={()=>act('stop')}><Button icon={<StopOutlined/>}>停止</Button></Popconfirm>}{['completed','stopped'].includes(batch.status)&&batch.failed>0&&<StartBatch retry={batch.id} type="default">重试未完成账号</StartBatch>}<Button icon={<DownloadOutlined/>} onClick={()=>download(`/batches/${batch.id}/export`,mode)}>导出汇总</Button></Space></div><div className="batch-progress"><Progress percent={Math.round((batch.completed+batch.failed+batch.skipped+batch.cancelled)/batch.total*100)} showInfo={false} strokeColor="#315fdf"/><span>已处理 <b>{number(batch.completed+batch.failed+batch.skipped+batch.cancelled)}</b> / {number(batch.total)} 个账号</span></div><div className="batch-metrics">{[['账号总数',batch.total,''],['成功完成',batch.completed,'green'],['失败 / 部分完成',batch.failed,'orange-text'],['已跳过 / 已取消',batch.skipped+batch.cancelled,'muted'],['执行中 / 待执行',batch.running+batch.pending,'blue-text'],['获得积分',batch.gained,'blue-text']].map(([label,value,color])=><div key={String(label)}><span>{label}</span><strong className={String(color)}>{number(value)}</strong></div>)}</div><TaskRuns key={batch.id} bid={batch.id}/></>:loading?<Skeleton active style={{padding:24}}/>:<div className="empty-large"><Empty description="还没有执行批次"/><StartBatch>创建第一个任务批次</StartBatch></div>}</section><Panel title="执行方案" className="profile-panel"><div className="profile-grid">{[['01','全量任务','逐项发现各业务任务，执行签到、SDK、网页、活动与权益，核对完成状态并记录未完成原因。'],['02','每日签到','执行业务签到、连签奖励和常规权益流程，记录平台返回与领取结果。'],['03','积分同步','仅查询当前余额，更新排行和账号积分，不执行任务动作。']].map(([n,t,d])=><div key={n}><span className="profile-no">{n}</span><div><h3>{t}</h3><p>{d}</p></div></div>)}</div></Panel></>
}

function Ranking(){
  const {mode,navigate}=useApp();const [page,setPage]=useState(1);const [q,setQ]=useState('');const [sort,setSort]=useState('points');const [detail,setDetail]=useState<number|null>(null)
  const {data,error,loading}=useLoad(`/accounts?sort=${sort}&page=${page}&page_size=20&q=${encodeURIComponent(q)}`);const overview=useLoad('/overview')
  return <><PageHead title="积分排行" description="按实际可用积分排序，快速找到高积分账号，让每一分都有价值。"><Button icon={<DownloadOutlined/>} onClick={()=>download(`/accounts/export?q=${encodeURIComponent(q)}`,mode)}>导出排行</Button><Button type="primary" icon={<ShopOutlined/>} onClick={()=>navigate('products')}>前往积分商城</Button></PageHead><LoadError error={error}/><div className="ranking-intro"><div className="ranking-emblem"><TrophyOutlined/></div><div><h2>所有账号，一张积分榜</h2><p>覆盖 {number(overview.data?.counts.total)} 个账号，汇总 {number(overview.data?.counts.points)} 积分。兑换后余额同步扣减。</p></div><div className="grow"/><span className="ranking-note"><SyncOutlined/> 通过任务中心同步最新积分</span></div><section className="panel table-panel"><div className="table-toolbar"><Segmented value={sort} options={[{value:'points',label:'可用积分排名'},{value:'gained',label:'最近收益排名'}]} onChange={v=>{setSort(String(v));setPage(1)}}/><div className="grow"/><Input.Search style={{width:290}} placeholder="搜索排行中的账号" allowClear onSearch={v=>{setQ(v);setPage(1)}}/></div><Table<Row> rowKey="id" loading={loading} dataSource={data?.items||[]} pagination={false} columns={[{title:'排名 / 账号',width:300,render:(_,r,i)=><AccountName row={r} rank={(page-1)*20+i+1}/>},{title:'来源',dataIndex:'source'},{title:'账号状态',dataIndex:'status',render:v=><Status value={v}/>},{title:'可用积分',dataIndex:'points',align:'right',render:v=><b className="rank-points">{balance(v)}</b>},{title:'最近收益',dataIndex:'gained',align:'right',render:v=><span className={v>0?'green':'muted'}>{v>0?'+':''}{number(v)}</span>},{title:'操作',width:140,align:'right',render:(_,r)=><a onClick={()=>setDetail(r.id)}>查看账号 <RightOutlined/></a>}]} scroll={{x:800}}/><div className="table-pagination"><span>全部 {number(data?.total)} 个账号参与排序</span><Pagination current={page} pageSize={20} total={data?.total||0} onChange={setPage} showSizeChanger={false}/></div></section>{detail!==null&&<AccountDrawer id={detail} onClose={()=>setDetail(null)}/>}</>
}

